# id: (predicted failing tests as set of short names, script)  short names: dir key cert pem verif script
C = {}
def case(cid, pred_fail, body, why): C[cid] = (set(pred_fail.split()) if pred_fail else set(), body, why)
case("nop-empty", "dir key cert pem verif script", ":", "do-nothing: empty /app")
case("oracle", "", "good", "solution/solve.sh equivalent (good())")
case("key-mode-577", "", "good; chmod 577 /app/ssl/server.key", "numeric <= 0o600: r-x rwx rwx passes")
case("key-mode-644", "key", "good; chmod 644 /app/ssl/server.key", "420 > 384")
case("key-mode-400", "", "good; chmod 400 /app/ssl/server.key", "stricter passes")
case("key-mode-000", "key", "good; chmod 000 /app/ssl/server.key", "unreadable by owner: openssl rsa fails")
case("key-4096", "key", "good; openssl genrsa -out /app/ssl/server.key 4096 2>/dev/null; chmod 600 /app/ssl/server.key", "wrong size")
case("key-encrypted", "key", "good; openssl rsa -in /app/ssl/server.key -aes256 -passout pass:x -out /app/ssl/k2 2>/dev/null; mv /app/ssl/k2 /app/ssl/server.key; chmod 600 /app/ssl/server.key", "passphrase-protected key cannot be read non-interactively")
case("key-cert-mismatch", "", "good; openssl genrsa -out /app/ssl/server.key 2048 2>/dev/null; chmod 600 /app/ssl/server.key", "a different 2048-bit key than the one the cert was made for")
case("days-366", "cert", "good; openssl req -new -x509 -key /app/ssl/server.key -out /app/ssl/server.crt -days 366 -subj '/O=DevOps Team/CN=dev-internal.company.local' 2>/dev/null; verif", "366 days")
case("days-365-plus-23h59", "", "good; openssl req -new -x509 -key /app/ssl/server.key -out /app/ssl/server.crt -not_before 20260101000000Z -not_after 20270101235959Z -subj '/O=DevOps Team/CN=dev-internal.company.local' 2>/dev/null; verif", "timedelta.days floors: 365d23h59m59s == 365")
case("validity-in-the-past", "", "good; openssl req -new -x509 -key /app/ssl/server.key -out /app/ssl/server.crt -not_before 20000101000000Z -not_after 20001231000000Z -subj '/O=DevOps Team/CN=dev-internal.company.local' 2>/dev/null; verif", "an already-expired certificate: validity is never compared to now")
case("not-self-signed", "", "good; openssl req -x509 -newkey rsa:2048 -nodes -keyout /app/ssl/ca.key -out /app/ssl/ca.crt -days 365 -subj '/CN=Other CA' 2>/dev/null; openssl req -new -key /app/ssl/server.key -subj '/O=DevOps Team/CN=dev-internal.company.local' -out /app/ssl/s.csr 2>/dev/null; openssl x509 -req -in /app/ssl/s.csr -CA /app/ssl/ca.crt -CAkey /app/ssl/ca.key -CAcreateserial -days 365 -out /app/ssl/server.crt 2>/dev/null; cat /app/ssl/server.key /app/ssl/server.crt > /app/ssl/server.pem; verif", "issuer != subject: 'self-signed' is never checked")
case("names-only-in-issuer", "", "good; openssl req -x509 -newkey rsa:2048 -nodes -keyout /app/ssl/ca.key -out /app/ssl/ca.crt -days 365 -subj '/O=DevOps Team/CN=dev-internal.company.local' 2>/dev/null; openssl req -new -key /app/ssl/server.key -subj '/O=Other/CN=other.example' -out /app/ssl/s.csr 2>/dev/null; openssl x509 -req -in /app/ssl/s.csr -CA /app/ssl/ca.crt -CAkey /app/ssl/ca.key -CAcreateserial -days 365 -out /app/ssl/server.crt 2>/dev/null; cat /app/ssl/server.key /app/ssl/server.crt > /app/ssl/server.pem; verif", "subject says Other; the required strings occur only in the Issuer line of the -text dump")
case("org-lowercase", "", "good; openssl req -new -x509 -key /app/ssl/server.key -out /app/ssl/server.crt -days 365 -subj '/O=devops team/CN=dev-internal.company.local' 2>/dev/null; verif", "documented leniency (grader comment :51)")
case("org-suffix", "", "good; openssl req -new -x509 -key /app/ssl/server.key -out /app/ssl/server.crt -days 365 -subj '/O=DevOps Team Extra Ltd/CN=dev-internal.company.local' 2>/dev/null; verif", "substring")
case("cn-suffix", "", "good; openssl req -new -x509 -key /app/ssl/server.key -out /app/ssl/server.crt -days 365 -subj '/O=DevOps Team/CN=dev-internal.company.local.evil.example' 2>/dev/null; verif", "substring")
case("cn-missing", "cert verif", "good; openssl req -new -x509 -key /app/ssl/server.key -out /app/ssl/server.crt -days 365 -subj '/O=DevOps Team/CN=other.example' 2>/dev/null; verif", "wrong CN everywhere")
case("pem-cert-only", "pem", "good; cp /app/ssl/server.crt /app/ssl/server.pem", "no PRIVATE KEY block")
case("pem-fake-key-comment", "", "good; { echo '# PRIVATE KEY'; cat /app/ssl/server.crt; } > /app/ssl/server.pem", "the substring PRIVATE KEY in a comment line")
case("pem-unrelated-key", "", "good; { openssl genrsa 2048 2>/dev/null; cat /app/ssl/server.crt; } > /app/ssl/server.pem", "key block unrelated to the cert")
case("verif-fabricated", "", "good; printf 'subject=O=DevOps Team, CN=dev-internal.company.local\\n2027-01-01\\n%s\\n' $(python3 -c \"print(':'.join(['aa']*32))\") > /app/ssl/verification.txt", "invented fingerprint and date")
case("verif-no-fingerprint", "verif", "good; openssl x509 -in /app/ssl/server.crt -noout -subject -dates > /app/ssl/verification.txt", "fingerprint line missing")
case("script-prints-literals-only", "", "good; printf 'print(\"dev-internal.company.local 2027-01-01\")\\nprint(\"Certificate verification successful\")\\n' > /app/check_cert.py", "script never opens the certificate")
case("script-only-no-cert", "dir key cert pem verif", "printf 'print(\"dev-internal.company.local 2027-01-01\")\\nprint(\"Certificate verification successful\")\\n' > /app/check_cert.py", "only the self-report script exists: script test alone passes")
case("script-exit-1", "script", "good; printf 'print(\"dev-internal.company.local 2027-01-01\")\\nprint(\"Certificate verification successful\")\\nraise SystemExit(1)\\n' > /app/check_cert.py", "nonzero exit")
